<?php
session_start(); require_once __DIR__ . '/includes/config.php';
if (empty($_SESSION['alogin']) || empty($_SESSION['uid'])) { header('Location: index.php'); exit; }
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
try {
 $totalActivos=(int)$dbh->query("SELECT COUNT(*) FROM activos")->fetchColumn();
 $asignacionesActivas=(int)$dbh->query("SELECT COUNT(*) FROM asignaciones WHERE estado_asignacion='ACTIVA'")->fetchColumn();
 $activosReparacion=(int)$dbh->query("SELECT COUNT(*) FROM activos WHERE estado='EN_REPARACION'")->fetchColumn();
 $mantenimientosPendientes=(int)$dbh->query("SELECT COUNT(*) FROM mantenimientos WHERE resultado='PENDIENTE'")->fetchColumn();
 $pendientes=$dbh->query("SELECT m.id,m.tipo_mantenimiento,m.fecha_programada,m.diagnostico,m.tecnico_responsable,a.codigo_inventario,a.descripcion AS activo,s.nombre AS sede,u.nombre AS ubicacion FROM mantenimientos m INNER JOIN activos a ON a.id=m.activo_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id LEFT JOIN sedes s ON s.id=u.sede_id WHERE m.resultado='PENDIENTE' ORDER BY m.fecha_programada IS NULL,m.fecha_programada ASC,m.id DESC LIMIT 10")->fetchAll(PDO::FETCH_ASSOC);
 $sqlRecientes="SELECT x.numero_control,x.fecha_asignacion,x.tipo_asignacion,x.funcionario_receptor,x.area_departamento_asignacion,a.codigo_inventario,a.descripcion AS activo,s.nombre AS sede,u.nombre AS ubicacion FROM asignaciones x INNER JOIN activos a ON a.id=x.activo_id LEFT JOIN ubicaciones u ON u.id=a.ubicacion_id LEFT JOIN sedes s ON s.id=u.sede_id ORDER BY x.fecha_creacion DESC,x.id DESC LIMIT 8";
 $asignacionesRecientes=$dbh->query($sqlRecientes)->fetchAll(PDO::FETCH_ASSOC);
} catch(PDOException $e){error_log('Error en dashboard SERVIUCIS: '.$e->getMessage());http_response_code(500);exit('No fue posible cargar el panel. Verifique que estén aplicadas las actualizaciones de asignaciones y la estructura de mantenimientos.');}
