</div>
<div class="row dashboard-section"><div class="col-md-12"><div class="panel"><div class="panel-heading"><div class="panel-title"><h5>Mantenimientos pendientes</h5></div><div class="pull-right" style="margin-top:-28px"><a href="add-mantenimiento.php" class="btn btn-primary btn-sm"><i class="fa fa-calendar-plus-o"></i> Programar individual</a> <a href="programar-masivo.php" class="btn btn-success btn-sm"><i class="fa fa-tasks"></i> Programar masivo</a> <a href="manage-mantenimientos.php" class="btn btn-default btn-sm">Ver todos</a></div></div><div class="panel-body p-20"><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Código inventario</th><th>Activo</th><th>Sede</th><th>Ubicación</th><th>Tipo</th><th>Actividad programada</th><th>Fecha programada</th><th>Responsable</th></tr></thead><tbody>
<?php if($pendientes): foreach($pendientes as $m): ?><tr><td><?php echo h($m['codigo_inventario']); ?></td><td><?php echo h($m['activo']); ?></td><td><?php echo h($m['sede']); ?></td><td><?php echo h($m['ubicacion']); ?></td><td><?php echo h(ucfirst(strtolower($m['tipo_mantenimiento']))); ?></td><td><?php echo h($m['diagnostico']); ?></td><td><?php echo h($m['fecha_programada']?:'Sin fecha'); ?></td><td><?php echo h($m['tecnico_responsable']?:'No definido'); ?></td></tr><?php endforeach; else: ?><tr><td colspan="8" class="text-center">No hay mantenimientos pendientes registrados.</td></tr><?php endif; ?></tbody></table></div><p class="text-muted">Se muestran los 10 mantenimientos pendientes más próximos o recientes.</p></div></div></div></div>
<div class="row dashboard-section"><div class="col-md-12"><div class="panel"><div class="panel-heading"><div class="panel-title"><h5>Asignaciones recientes</h5></div></div><div class="panel-body p-20"><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>N.º control</th><th>Código inventario</th><th>Activo</th><th>Modalidad</th><th>Funcionario receptor</th><th>Área/departamento</th><th>Sede</th><th>Ubicación</th><th>Fecha</th></tr></thead><tbody>
<?php if($asignacionesRecientes): foreach($asignacionesRecientes as $a): ?><tr><td><?php echo h($a['numero_control']); ?></td><td><?php echo h($a['codigo_inventario']); ?></td><td><?php echo h($a['activo']); ?></td><td><?php echo $a['tipo_asignacion']==='PERSONA'?'Entrega a persona':'Uso compartido en sede'; ?></td><td><?php echo h($a['funcionario_receptor']?:'No aplica'); ?></td><td><?php echo h($a['area_departamento_asignacion']?:'—'); ?></td><td><?php echo h($a['sede']); ?></td><td><?php echo h($a['ubicacion']); ?></td><td><?php echo h($a['fecha_asignacion']); ?></td></tr><?php endforeach; else: ?><tr><td colspan="9" class="text-center">Todavía no hay asignaciones registradas.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div>
</div></section></div></div></div><?php include __DIR__.'/includes/footer.php'; ?>
